    concatenated = lst[0] + lst[1]
    n = len(concatenated)

    for i in range(1 << n):
        temp = ''
        for j in range(n):
            if i & (1 << j):
                temp += concatenated[j]
        if is_balanced(temp):
            return 'Yes'

    return 'No'

