def match_parens(lst):
    if len(lst) != 2:
        return 'No'

    for string in lst:
        if not all(char in ['(', ')'] for char in string):
            return 'No'

    open_count = lst[0].count('(') + lst[1].count('(')
    close_count = lst[0].count(')') + lst[1].count(')')

    if open_count != close_count:
        return 'No'

    stack = []
    for char in lst[0] + lst[1]:
        if char == '(':
            stack.append('(')
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    return 'Yes'

